import{_ as i,C as r,o as s,c as n,a9 as t,E as o}from"./chunks/framework.asyjyako.js";const f=JSON.parse('{"title":"Compare versions and revisions","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/comparisons.md","filePath":"tutorials/comparisons.md","lastUpdated":null}'),l={name:"tutorials/comparisons.md"};function c(h,e,d,p,m,g){const a=r("DocMedia");return s(),n("div",null,[e[0]||(e[0]=t(`<h1 id="Compare-versions-and-revisions" tabindex="-1">Compare versions and revisions <a class="header-anchor" href="#Compare-versions-and-revisions" aria-label="Permalink to &quot;Compare versions and revisions {#Compare-versions-and-revisions}&quot;">​</a></h1><p>The version history in the <a href="./quick-tour">operation benchmark</a> shows how Bibliography export changed across releases. A release can also update its dependencies, so that history does not isolate a particular source change. For that, we will compare two commits while keeping the dependencies fixed.</p><p>The <em>baseline</em> is the revision we compare against. The <em>candidate</em> is the revision we want to evaluate. Here the candidate changes BibTeX export from concatenating per-entry strings to writing entries into one buffer.</p><h2 id="Run-the-two-revision-example" tabindex="-1">Run the two-revision example <a class="header-anchor" href="#Run-the-two-revision-example" aria-label="Permalink to &quot;Run the two-revision example {#Run-the-two-revision-example}&quot;">​</a></h2><p>Use the <code>examples/bibliography/</code> directory and controller environment prepared in the <a href="./quick-tour">operation benchmark</a>. Inspect the selected revisions, then run the comparison:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare-exports.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare-exports.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>The script selects <code>export_bibtex</code> with BenchmarkTools. It compares parent <code>6a4cc90</code> with the <a href="https://github.com/JuliaBibliographies/Bibliography.jl/commit/575ec810042cc791fd47a2c025a80246ccf039b5" target="_blank" rel="noreferrer">streaming-export commit <code>575ec81</code></a>, using the BibInternal and BibParser revisions in <code>sources.toml</code> for both. Each revision gets 100 samples, one evaluation per sample and one worker thread.</p><p>The terminal prints a new <code>results/export-comparison-*</code> directory. Its report contains the measurements and the exact revisions used.</p><h2 id="Read-the-result" tabindex="-1">Read the result <a class="header-anchor" href="#Read-the-result" aria-label="Permalink to &quot;Read the result {#Read-the-result}&quot;">​</a></h2><p>The recorded run used Windows and Julia 1.13.0 on 12 September 2026:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Median measurement</th><th style="text-align:right;">Parent <code>6a4cc90</code></th><th style="text-align:right;">Streaming export <code>575ec81</code></th><th style="text-align:right;">Change</th></tr></thead><tbody><tr><td style="text-align:right;">Allocated bytes</td><td style="text-align:right;">3,904 B</td><td style="text-align:right;">2,976 B</td><td style="text-align:right;">−23.77%</td></tr><tr><td style="text-align:right;">Allocation count</td><td style="text-align:right;">27</td><td style="text-align:right;">23</td><td style="text-align:right;">−14.81%</td></tr><tr><td style="text-align:right;">Elapsed time</td><td style="text-align:right;">7,600 ns</td><td style="text-align:right;">6,800 ns</td><td style="text-align:right;">−10.53%</td></tr><tr><td style="text-align:right;">Garbage collection time</td><td style="text-align:right;">0 ns</td><td style="text-align:right;">0 ns</td><td style="text-align:right;">No relative change defined</td></tr></tbody></table>`,11)),o(a,{src:"/examples/bibliography/figures/streaming-comparison.svg",alt:"Before and after a Bibliography streaming export change: bytes 3904 to 2976, allocations 27 to 23, median time 7.6 to 6.8 microseconds",caption:"100 samples per revision, with fixed dependency versions. The timing distributions overlap."}),e[1]||(e[1]=t('<p>The candidate allocates 928 fewer bytes and creates four fewer allocations per export. Its median time is also lower, but the timing samples overlap. Repeating this pair with larger bibliographies would help determine how the change behaves on more demanding inputs.</p><p>The report is <code>inconclusive</code> because the example has no acceptance limits. Both GC values are zero, so a relative GC change is undefined. The benchmark also has no correctness oracle: check the exported documents separately before accepting the optimization. An <em>oracle</em> is the check that an operation produced the expected result, such as retaining the citation keys and titles.</p><p><a href="../examples/bibliography/streaming-comparison.json" download>Download the comparison measurements</a></p><h2 id="Compare-your-own-change" tabindex="-1">Compare your own change <a class="header-anchor" href="#Compare-your-own-change" aria-label="Permalink to &quot;Compare your own change {#Compare-your-own-change}&quot;">​</a></h2><p>Keep the input and measurement settings fixed, choose a baseline commit and add the candidate revision to your suite. Save full commit hashes when a branch may move. Use the same dependency versions for a source-code comparison; let Pkg resolve each release&#39;s dependencies when comparing complete released stacks.</p><p>The <a href="./../reference/comparisons">comparison reference</a> describes the Julia constructors, grouped baselines and command-line options. For a graphical selection, use the <a href="/PerfChecker/dev/reference/comparisons#Use-the-VS-Code-target-picker">VS Code target picker</a>.</p><h2 id="Investigate-the-difference" tabindex="-1">Investigate the difference <a class="header-anchor" href="#Investigate-the-difference" aria-label="Permalink to &quot;Investigate the difference {#Investigate-the-difference}&quot;">​</a></h2><p>Timings locate a change between revisions. A profile helps locate the calls responsible for it. Continue with <a href="./../guide/investigate">investigating a performance change</a> to read Bibliography&#39;s allocation and CPU profiles. Once you have a useful comparison, <a href="./ci">CI checks</a> can apply limits to future changes.</p><details class="reference-details"><summary>Configuration reference</summary><p id="Define-candidates-in-Julia"><a href="../reference/comparisons#Define-candidates-in-Julia">Define candidates in Julia</a></p><p id="Exact-and-grouped-references"><a href="../reference/comparisons#Exact-and-grouped-references">Exact and grouped references</a></p><p id="Use-the-VS-Code-target-picker"><a href="../reference/comparisons#Use-the-VS-Code-target-picker">VS Code target picker</a></p><p id="Use-repeated-CLI-targets"><a href="../reference/comparisons#Use-repeated-CLI-targets">Command-line targets</a></p><p id="Comparability-rules"><a href="../reference/comparisons#Comparability-rules">Comparability rules</a></p></details>',9))])}const b=i(l,[["render",c]]);export{f as __pageData,b as default};
